CREATE DATABASE IF NOT EXISTS GP3_nombre_base CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE GP3_nombre_base;
CREATE TABLE IF NOT EXISTS Socios (ID_Socio INT AUTO_INCREMENT PRIMARY KEY,DNI VARCHAR(20) NOT NULL UNIQUE,Nombre VARCHAR(80) NOT NULL,Apellido VARCHAR(80) NOT NULL,Edad INT,Correo VARCHAR(120) UNIQUE,Telefono VARCHAR(30),Estado BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS Entrenadores (ID_Entrenador INT AUTO_INCREMENT PRIMARY KEY,DNI VARCHAR(20) NOT NULL UNIQUE,Nombre VARCHAR(80) NOT NULL,Apellido VARCHAR(80) NOT NULL,Especialidad VARCHAR(80),Estado BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS Clases (ID_Clase INT AUTO_INCREMENT PRIMARY KEY,Disciplina VARCHAR(100) NOT NULL,ID_Entrenador INT NOT NULL,Horario TIME NOT NULL,Capacidad INT NOT NULL,Estado BOOLEAN DEFAULT TRUE,FOREIGN KEY (ID_Entrenador) REFERENCES Entrenadores(ID_Entrenador));
CREATE TABLE IF NOT EXISTS Pases (ID_Pase INT AUTO_INCREMENT PRIMARY KEY,ID_Socio INT NOT NULL,CantidadEntradas INT NOT NULL,Fecha_Inicio DATE NOT NULL,Fecha_Fin DATE NOT NULL,Costo DECIMAL(12,2) NOT NULL,Estado BOOLEAN DEFAULT TRUE,FOREIGN KEY (ID_Socio) REFERENCES Socios(ID_Socio));
CREATE TABLE IF NOT EXISTS Asistencias (ID_Asistencia INT AUTO_INCREMENT PRIMARY KEY,ID_Socio INT NOT NULL,ID_Clase INT NOT NULL,Fecha_Asistencia DATE NOT NULL,FOREIGN KEY (ID_Socio) REFERENCES Socios(ID_Socio),FOREIGN KEY (ID_Clase) REFERENCES Clases(ID_Clase));
INSERT INTO Socios (DNI,Nombre,Apellido,Edad,Correo,Telefono,Estado) VALUES ('30111222','Ana','Lopez',25,'ana.aborigym@example.com','2664000000',TRUE) ON DUPLICATE KEY UPDATE Nombre=VALUES(Nombre);
INSERT INTO Entrenadores (DNI,Nombre,Apellido,Especialidad,Estado) VALUES ('28111222','Carlos','Perez','Musculacion',TRUE) ON DUPLICATE KEY UPDATE Nombre=VALUES(Nombre);
INSERT INTO Clases (Disciplina,ID_Entrenador,Horario,Capacidad,Estado) SELECT 'Musculacion',ID_Entrenador,'09:00:00',20,TRUE FROM Entrenadores WHERE DNI='28111222' AND NOT EXISTS (SELECT 1 FROM Clases WHERE Disciplina='Musculacion' AND Horario='09:00:00');
INSERT INTO Pases (ID_Socio,CantidadEntradas,Fecha_Inicio,Fecha_Fin,Costo,Estado) SELECT ID_Socio,12,CURDATE(),DATE_ADD(CURDATE(),INTERVAL 30 DAY),30000,TRUE FROM Socios WHERE DNI='30111222' AND NOT EXISTS (SELECT 1 FROM Pases WHERE ID_Socio=Socios.ID_Socio);
